import {midi} from './engine.mjs';
const $=id=>document.getElementById(id);const worker=new Worker('./worker.mjs',{type:'module'});
let current,midiURL,audioURL,audioWorker,renderAbort,version=0;
let history;try{history=JSON.parse(localStorage.getItem('cadenza-library')||'[]');}catch{history=[];}
function library(){const list=$('library-list');list.replaceChildren();for(const p of history){const b=document.createElement('button');b.className='library-item';b.textContent=p.title;b.onclick=()=>show(p,midi(p));list.append(b);}}
function stopAudio(){const player=$('audio-preview');player.pause();player.removeAttribute('src');player.load();player.hidden=true;$('download-audio').hidden=true;if(audioURL)URL.revokeObjectURL(audioURL);if(audioWorker)audioWorker.terminate();if(renderAbort)renderAbort.abort();}
$('generate').onclick=()=>{version++;stopAudio();$('generate').disabled=true;$('status').textContent='Developing eight fresh compositions…';worker.postMessage({palette:$('palette').value});};
worker.onerror=()=>{$('generate').disabled=false;$('status').textContent='The model could not load. Check the installation or connection and try again.';};
worker.onmessage=({data})=>{if(data.type==='status'){$('status').textContent=data.message;return;}$('generate').disabled=false;if(data.type==='error'){$('status').textContent=data.message;return;}history.unshift(data.piece);history=history.slice(0,30);try{localStorage.setItem('cadenza-library',JSON.stringify(history));}catch{$('storage-note').textContent='Storage is full. Download MIDI to keep this composition.';}library();show(data.piece,data.bytes);};
async function show(piece,bytes){version++;const thisVersion=version;stopAudio();current=piece;if(midiURL)URL.revokeObjectURL(midiURL);midiURL=URL.createObjectURL(new Blob([bytes],{type:'audio/midi'}));const filename=piece.title.replace(/[^a-z0-9-]/gi,'_');$('title').textContent=piece.title;$('download').href=midiURL;$('download').download=filename+'.mid';$('result').hidden=false;$('empty').hidden=true;const s=Math.round(piece.seconds);$('detail').textContent=piece.instrument_names.join(' + ')+' · '+piece.bpm+' BPM · '+Math.floor(s/60)+':'+String(s%60).padStart(2,'0');draw();$('status').textContent='MIDI saved to your library. Rendering recorded instruments…';
 function audio(blob,extension){if(version!==thisVersion)return;audioURL=URL.createObjectURL(blob);$('audio-preview').src=audioURL;$('audio-preview').hidden=false;$('download-audio').href=audioURL;$('download-audio').download=filename+'.'+extension;$('download-audio').textContent='Save '+extension.toUpperCase();$('download-audio').hidden=false;$('status').textContent='Ready to listen. Your note data is saved in this browser.';$('audio-status').textContent=extension==='m4a'?'Recorded instruments · AAC audio':'Recorded instruments · WAV audio. Desktop app also exports M4A.';}
 try{const caps=await fetch('./api/capabilities');if(caps.ok&&(await caps.json()).m4a){renderAbort=new AbortController();const r=await fetch('./api/render',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(piece),signal:renderAbort.signal});if(!r.ok)throw Error('Local audio rendering failed.');audio(await r.blob(),'m4a');return;}}catch(e){if(e.name==='AbortError')return;}
 if(version!==thisVersion)return;audioWorker=new Worker('./audio-worker.mjs',{type:'module'});audioWorker.onmessage=({data})=>{if(version!==thisVersion)return;if(data.type==='audio')audio(new Blob([data.wav],{type:'audio/wav'}),'wav');else $('status').textContent='MIDI is ready. '+data.message;audioWorker.terminate();};audioWorker.onerror=()=>{$('status').textContent='MIDI is ready. Audio could not render on this device.';};audioWorker.postMessage({piece,bytes});
}
function draw(){if(!current)return;const canvas=$('roll'),rect=canvas.getBoundingClientRect(),dpr=devicePixelRatio||1;canvas.width=rect.width*dpr;canvas.height=180*dpr;const ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);const width=rect.width;ctx.fillStyle='#24353d';for(let i=0;i<current.bars;i++)ctx.fillRect(i*width/current.bars,0,1,180);for(const n of current.notes){ctx.fillStyle=n.voice?'#568983':'#c6e7ae';ctx.fillRect(n.beat/(current.bars*4)*width,165-(n.pitch-30)/70*150,Math.max(2,n.duration/(current.bars*4)*width),3);}}
window.addEventListener('resize',draw);library();
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
